import{_ as e}from"./chunks/panel-workspace.DfVZw37W.js";import{_ as d,a as i,b as s}from"./chunks/theme-dark.DMCpB48j.js";import{_ as n,C as l,o as c,c as g,a2 as t,j as h,a,E as m}from"./chunks/framework.Dx-TCpNt.js";const Y=JSON.parse('{"title":"はじめに","description":"KomaYomi（Manga Learner）は、「1ページを複数の言語で読み比べる」ためのローカル優先 Web アプリです。日本語を勉強していて翻訳版を横に置きたい人、翻訳版と生肉を突き合わせて確認したい人、あのセリフが各版でどうなっているのか知りたい人——どれも歓迎です。ページをコマに分割し…","frontmatter":{"description":"KomaYomi（Manga Learner）は、「1ページを複数の言語で読み比べる」ためのローカル優先 Web アプリです。日本語を勉強していて翻訳版を横に置きたい人、翻訳版と生肉を突き合わせて確認したい人、あのセリフが各版でどうなっているのか知りたい人——どれも歓迎です。ページをコマに分割し…"},"headers":[],"relativePath":"ja/guide/introduction.md","filePath":"ja/guide/introduction.md","lastUpdated":1794833124000}'),p={name:"ja/guide/introduction.md"};function u(f,o,b,_,j,q){const r=l("Badge");return c(),g("div",null,[o[2]||(o[2]=t('<h1 id="はじめに" tabindex="-1">はじめに <a class="header-anchor" href="#はじめに" aria-label="Permalink to &quot;はじめに&quot;">​</a></h1><p>KomaYomi（<strong>Manga Learner</strong>）は、「1ページを複数の言語で読み比べる」ためのローカル優先 Web アプリです。日本語を勉強していて翻訳版を横に置きたい人、翻訳版と生肉を突き合わせて確認したい人、あのセリフが各版でどうなっているのか知りたい人——どれも歓迎です。ページをコマに分割し、同じコマを日本語・中国語・英語で並べ、Markdown ノート（訳注、写植の相談、語彙メモ）をそのコマに貼り付けられます。</p><p>気軽な読書用のマンガリーダーでも、配信プラットフォームでもありません。すべては自分のマシン上で、自分の画像フォルダだけを相手に動きます。</p><h2 id="解決する課題" tabindex="-1">解決する課題 <a class="header-anchor" href="#解決する課題" aria-label="Permalink to &quot;解決する課題&quot;">​</a></h2><p>翻訳の勉強は、ページ単位よりコマ単位のほうが捗ります。ただ、同じ本のスキャンを3言語そろえても、そう都合よくはそろいません。ページはずれ、コマの切り出しは違い、文字の位置もそれぞれ。普通の画像ビューアではズームは1段階きり、ノートも取れず、「この吹き出し、3つの版でどうなってる？」と聞くこともできません。</p><p>KomaYomi は、その間に欠けている層を足します。</p><ol><li><strong>構造</strong> — コマは正規化した矩形として保存されるので、ズームしてもウィンドウを変えても、書き出しサイズが変わっても枠は生き残ります。</li><li><strong>位置合わせ</strong> — 言語ごとに個別にずらして、同じコマをちゃんと重ねられます。ようやく。</li><li><strong>ノート</strong> — 所見はページかコマに紐付き、タグと出典付きの Markdown で残せます。「あとで覚えておく」はもう作戦にはなりません。</li></ol><h2 id="_5ステップのワークフロー" tabindex="-1">5ステップのワークフロー <a class="header-anchor" href="#_5ステップのワークフロー" aria-label="Permalink to &quot;5ステップのワークフロー&quot;">​</a></h2><table tabindex="0"><thead><tr><th>手順</th><th>行うこと</th><th>ページ</th></tr></thead><tbody><tr><td>1</td><td>生肉と翻訳版を <code>raw/&lt;volume&gt;/&lt;language&gt;/&lt;chapter&gt;/01.jpg</code> に整理するか、すでにあるフォルダを指定します。</td><td><a href="/KomaYomi-docs/ja/guide/preprocess">画像の前処理と名前変更</a>、<a href="/KomaYomi-docs/ja/guide/gallery">ライブラリとインポート</a></td></tr><tr><td>2</td><td>ページを開いて自動分割を実行し、枠を手作業で修正します。自動検出は下書きであって、結論ではありません。</td><td><a href="/KomaYomi-docs/ja/guide/panels">コマ分割ワークベンチ</a></td></tr><tr><td>3</td><td>複数言語を並列または重ね表示で読み、位置合わせを行い、確認したい言語をマスクします。</td><td><a href="/KomaYomi-docs/ja/guide/compare">比較リーダー</a></td></tr><tr><td>4</td><td>タグ、出典、スクリーンショット付きのページノートとコマノートを書きます。訳注も大歓迎です。</td><td><a href="/KomaYomi-docs/ja/guide/notes">ノート</a></td></tr><tr><td>5</td><td>学習用 HTML、スライド用 PNG、別のマシン用のプロジェクトパッケージをエクスポートします。</td><td><a href="/KomaYomi-docs/ja/guide/export">エクスポート</a></td></tr></tbody></table><h2 id="画面の構成" tabindex="-1">画面の構成 <a class="header-anchor" href="#画面の構成" aria-label="Permalink to &quot;画面の構成&quot;">​</a></h2><figure class="shot"><img src="'+e+'" alt="漫画ページ、検出されたコマ、リサイズハンドル、注釈ツールバーを表示したコマ分割ワークベンチ"><figcaption>コマ分割ワークベンチ。上部バー：ページ移動、コマ / 比較読み、読み順、テーマ、表示言語、ノート、エクスポート。左：ライブラリ。右：ノート。中央：コマ枠付きのページ——いちばん長居する場所です。</figcaption></figure><p>ウィンドウには、常に同じ位置にある5つの領域があります。慣れれば指が覚えてくれます。</p><ul><li><strong>上部バー</strong> — ブランド（ライブラリに戻る）、巻 / 話 / ページ、<code>‹</code> <code>›</code> のページ矢印、保存インジケーター、<strong>編集 / 閲覧</strong> の使用モード、<strong>コマ / 比較読み / 原版</strong> の切り替え、読み順のセレクター、集中モード（<code>⛶</code>）、ヘルプ（<code>?</code>）、設定（<code>⚙</code>、編集モードのみ）、アプリ情報（<code>ⓘ</code>）、UI テーマ、表示言語、<strong>ノート</strong>、<strong>エクスポート</strong>。</li><li><strong>ライブラリサイドバー</strong>（<code>S</code>） — 巻 → 話 → ページ。ページごとの警告に加え、マンガの追加、フォルダ規則、プロジェクトファイル、交換ファイル、バックアップへの入口があります。</li><li><strong>ステージ</strong> — 表示の切り替えに応じて、コマ分割ワークベンチ、比較リーダー、または原版ビューを表示します。</li><li><strong>ノート列</strong>（<code>N</code>） — ページノート、コマノート、一覧検索、一時メモ。</li><li><strong>ペインスプリッター</strong> — ライブラリとステージの間、またはステージとノートの間の縦ハンドルをドラッグしてサイズを変更します。ダブルクリックで既定値に戻ります。</li></ul><p>ページは任意の数の言語を持てます。比較リーダーの言語チップは、現在のページに存在する言語だけが有効になります。</p><p>ウィンドウが狭くなっても、上部バーとコマ分割ワークベンチのツールバーは無理に詰め込みません。入りきらない次要の操作は <code>≡</code> のオーバーフローメニューにまとまり、スマートフォン幅ではページ送りや表示切り替えなど必要最小限だけが残ります。メニューの中身は広い画面のボタンと同じで、入口が消えることはありません。</p><h2 id="スタート画面" tabindex="-1">スタート画面 <a class="header-anchor" href="#スタート画面" aria-label="Permalink to &quot;スタート画面&quot;">​</a></h2><p>ライブラリを開く前は、スタート画面が表示されます。<strong>画像をインポート / フォルダをスキャン</strong>、<strong>ライブラリを新規作成</strong>、<strong><code>.mnproj</code> を開く</strong>、<strong>ガイド</strong> の4つの入口があり、初回の6ステップをカードで並べます。スキャンを取り込む、ライブラリを作るかプロジェクトを開く、ページを選ぶ、コマを分割する、言語を比較する、最後に注釈とエクスポートです。</p><p>カードは広い画面で 3×2、中くらいの幅で 2×3、狭い画面で1列になります。読み取り専用モードではインポートと新規作成の入口が隠れ、プロジェクトを開く・ガイドだけが残ります。</p><h2 id="編集モードと閲覧モード" tabindex="-1">編集モードと閲覧モード <a class="header-anchor" href="#編集モードと閲覧モード" aria-label="Permalink to &quot;編集モードと閲覧モード&quot;">​</a></h2><p>上部バー中央の <strong>編集 / 閲覧</strong> 切り替えで、このワークスペースが作業台か閲覧ビューアかが決まります。選択はブラウザーに保存され、再読み込みしても維持されます。</p><ul><li><strong>編集モード</strong> — コマ分割、注釈、ノート、読み順の変更ができ、変更は保存モードに従って <code>data/</code> に書き込まれます。初めて開くページはコマの自動検出も走ります。</li><li><strong>閲覧モード</strong> — 切り替えると、まだ保存していない現在ページの変更を先に保存し、コマの選択を解除して履歴と設定のダイアログを閉じます。上部バーに <strong>読み取り専用</strong> のバッジが出ます。完成した成果を人に見せるときや、誤って編集したくない復習に向いています。</li></ul><p>閲覧モードで無効になる操作：</p><table tabindex="0"><thead><tr><th>領域</th><th>閲覧モードでの動作</th></tr></thead><tbody><tr><td>コマ分割ワークベンチ</td><td>分割・編集ツールバー、保存 / 履歴、グリッドとテンプレート、注釈の描画ツール、キーボードでの微調整が非表示または無効になり、ズームとパンだけが使えます。</td></tr><tr><td>比較リーダー</td><td>注釈の描画ツールは隠れ、既存の注釈はそのまま表示されます。位置合わせのプリセットやアンカー入力など、データを書き込む操作は非表示です。ドラッグとホイールによる一時的なパン / ズームはできますが、ページには書き戻されません。</td></tr><tr><td>ノート列</td><td>閲覧と検索のみになり、「閲覧モードではノートは閲覧のみ」と表示されます。新規作成、編集、削除、一時メモは使えません。</td></tr><tr><td>ライブラリサイドバー</td><td>マンガの追加、巻設定の歯車、前処理、プラグイン、フォルダー規則、バックアップが隠れます。プロジェクトファイル、最近のページ、再読み込みは残ります。</td></tr><tr><td>上部バーとファイルメニュー</td><td>読み順セレクターは無効になり、ファイルメニューはプロジェクトを開く・最近のページ・エクスポートだけになります。<code>Ctrl+S</code> では保存されません。</td></tr></tbody></table><p>これらの制限はボタンを隠すだけではありません。閲覧モード中は書き込みリクエストがサーバー側で拒否されます（<code>ERR_READ_ONLY</code>）。エクスポート、プレビュー、プロジェクトの検査は引き続き使えます。</p><h2 id="集中モード" tabindex="-1">集中モード <a class="header-anchor" href="#集中モード" aria-label="Permalink to &quot;集中モード&quot;">​</a></h2><p>集中モード（上部バーの <code>⛶</code> ボタン、または <code>R</code>）は別の機能です。上部バー、ステージのツールバー、コマのセクションレール、ステータスバーを一時的に隠してページを画面いっぱいに広げるだけで、編集 / 閲覧モードは変わりません。<code>Esc</code> または <code>R</code> で戻り、タッチ端末では空白部分をダブルタップして終了します。入ったときに終了方法を短く表示しますが、自動で消え、絵の上に居座ることはありません。</p><h2 id="最初の10分" tabindex="-1">最初の10分 <a class="header-anchor" href="#最初の10分" aria-label="Permalink to &quot;最初の10分&quot;">​</a></h2><ol><li>まずアプリを動かします。リポジトリで <code>npm run dev</code> を実行するか、デスクトップ版を起動して、<code>http://127.0.0.1:5173</code> を開いてください。</li><li>ライブラリに1巻分を認識させます。<code>raw/</code> に置くか、サイドバーの <strong>＋ マンガを追加</strong> から手持ちのフォルダを指定します。</li><li>サイドバーでページを開きます。初回はコマの自動検出が走り、結果は <code>data/pages/</code> に保存されます。</li><li>2言語を見比べたいときは <strong>比較読み</strong>（<code>C</code>）に切り替え、<code>JA</code> と <code>ZH</code> にチェックを入れて、同じコマが上下でそろうまで片方のペインをドラッグします。ページ全体をいじるより、コマ単位で合わせるほうがずっと楽です。</li><li>書き留めたいところが出てきたら <strong>ノート</strong>（<code>N</code>）を開き、コマを選んで最初のノートを書きます。保存は <code>Ctrl+Enter</code> です。</li><li>最後に <code>E</code> で HTML をエクスポートし、ブラウザで開いてみてください。</li></ol><h2 id="実装済みの機能" tabindex="-1">実装済みの機能 <a class="header-anchor" href="#実装済みの機能" aria-label="Permalink to &quot;実装済みの機能&quot;">​</a></h2><div class="status-list"><div><strong>ライブラリ</strong> — 巻をスキャンし、1つのルートに複数作品が並ぶ構成にも対応し、言語フォルダの別名を認識し、ページを並び順で対応付け、欠けているページや命名の不一致を警告します。サイドバーのページ一覧は 2 列サムネイル、1 列サムネイル、言語とノート数付きのリストから選べ、ブラウザごとに記憶されます。</div><div><strong>コマ</strong> — XY カットによる自動検出、追加 / 移動 / 8方向のリサイズ / 結合 / グループ化 / 分割 / 削除、1–10 のクイック位置と右クリック移動に対応した番号の手動並べ替え、パーセント入力、グリッド生成、コマテンプレート、宣言的レイアウト、プラグイン、セッションをまたぐページ版履歴。</div><div><strong>注釈</strong> — 矢印、矩形、楕円、マーカー、フリーハンドペン、テキスト、番号バッジ、モザイク、任意のアンカーと引き出し線、ページ単位の表示切り替え、PNG エクスポート対応。</div><div><strong>比較</strong> — 複数言語、並列または重ね表示、言語ごとのぼかし / 塗りつぶしマスク、ホイールズーム、パン、ページ / コマ / アンカー / グリッドの位置合わせ、保存済みプリセット、言語順のカスタマイズ。さらに原版ビュー（ズームとパンを連動 / 独立で切り替え）、ページ・話をまたぐ前のコマ / 次のコマ、コマ ID による深リンク付きのコマ詳細ビュー。比較リーダーの行（言語ペイン、見出し、余白）をダブルクリックするとそのコマが開き、詳細ビューではセッション限りの言語別位置合わせが使えます。</div><div><strong>ノート</strong> — ページ / コマのノートをいくつでも、ツールバーとライブプレビュー付きの Markdown、既存ノートを同じ単一エディターで編集、タグ、出典、添付画像、一覧検索、LLM 用コピー、一時メモ。さらにノートの種類として背景知識 / 単語 / つぶやき、有効な言語ごとの種類、`data/library.json` に保存するカスタム種類があります。ノート列は 絞り込み → 一覧 → エディター の順で、グループ化と種類別の追加に対応し、コマ詳細ビューにも同じエディターが埋め込まれます。</div><div><strong>エクスポート</strong> — HTML（画像フォルダまたは単一ファイル）、PNG（ページ全体、現在のコマ、3言語コラージュ）、ブラウザの印刷ダイアログ経由の PDF、ページ画像とノートを含み注釈を既定で焼き込む Word（`.docx`）、コマ枠の重ね描き、印刷用スタイル、エクスポートテンプレート。</div><div><strong>モード</strong> — 編集 / 閲覧の2モード。閲覧に切り替えると先に保存してからすべての書き込みを無効にします。集中モード（`R`）で画面を没入表示にできます。</div><div><strong>ストレージ</strong> — ローカルフォルダ、マウントしたネットワーク共有、WebDAV。オンデマンドの画像取得、上限付き LRU キャッシュ、定期的な自動バックアップとキャッシュ管理に対応します。ページの書き込みはアトミックでスキーマ検証を行い、`.bak` をローテーションし、ページごとの書き込みロックを取ります。</div><div><strong>可搬性</strong> — `.mnproj` プロジェクトパッケージ、`.mntpl` / `.mnexp` / `.mnpage.json` の交換ファイル、バックアップと復元の ZIP、バージョン付きスキーマ（ページとプロジェクトのドキュメントは 2）。</div></div><h2 id="未実装の機能" tabindex="-1">未実装の機能 <a class="header-anchor" href="#未実装の機能" aria-label="Permalink to &quot;未実装の機能&quot;">​</a></h2>',31)),h("p",null,[o[0]||(o[0]=a("以下の項目は、登場する箇所で ",-1)),m(r,{type:"warning",text:"予定"}),o[1]||(o[1]=a(" と表示されます。",-1))]),o[3]||(o[3]=t('<ul><li>語彙リストのエクスポート。PDF と Word はエクスポートダイアログの <strong>PDF（印刷）</strong> と <strong>Word 文書</strong> から利用できます。</li><li>アプリ内の画像形式変換。名前変更と分割は<a href="/KomaYomi-docs/ja/guide/preprocess">前処理</a>に含まれます。形式変換はアプリの外で行ってください。</li><li>完全なネイティブモバイルアプリ。Web UI は狭いブラウザウィンドウでも動作します（下記参照）。</li><li>インポート / エクスポートの往復を対象とした、より広範な自動統合テスト。</li></ul><figure class="shot"><img src="'+d+'" alt="言語ペインが縦に積み重なった、狭いウィンドウの比較リーダー"><figcaption>狭いウィンドウ：ペインは縦に積み重なり、ライブラリはドロワーになります。ネイティブアプリではなくレスポンシブな Web レイアウトですが、スマホくらいの画面でもちゃんと動きます。</figcaption></figure><h2 id="ライトとダーク" tabindex="-1">ライトとダーク <a class="header-anchor" href="#ライトとダーク" aria-label="Permalink to &quot;ライトとダーク&quot;">​</a></h2><p>UI テーマは既定でシステムに従い、上部バーからライトまたはダークに固定できます。エクスポートされる HTML はライトテーマのみなので、スクリーンショットや印刷結果が一定になります。</p><figure class="shot"><img src="'+i+'" alt="ライトテーマの比較リーダー"><figcaption>ライトテーマ。</figcaption></figure><figure class="shot"><img src="'+s+'" alt="ダークテーマの比較リーダー"><figcaption>ダークテーマ。</figcaption></figure><h2 id="よくある落とし穴" tabindex="-1">よくある落とし穴 <a class="header-anchor" href="#よくある落とし穴" aria-label="Permalink to &quot;よくある落とし穴&quot;">​</a></h2><ul><li><strong>ライブラリに何も出ない。</strong> サイドバーは <code>raw/</code> だけを走査します。先にフォルダーを追加するか、リモートツリーをマウントしてください。<a href="/KomaYomi-docs/ja/guide/gallery">ライブラリと取り込み</a> を参照。</li><li><strong>最初のページのコマがずれている。</strong> 自動検出は下書きで、結論ではありません。コマ単位のノートを書く前に枠を直してください。あとで再検出すると手作業の修正は失われます。</li><li><strong>言語チップが灰色。</strong> そのページにその言語の画像がありません。ページ数と言語の対応付けを確認してください。</li><li><strong>別のマシンでノートが消えたように見える。</strong> ノートは <code>data/</code>、画像は <code>raw/</code> にあります。両方を移すか、<code>.mnproj</code> を書き出してください。<a href="/KomaYomi-docs/ja/guide/project-files">プロジェクトファイルと形式</a> を参照。</li><li><strong>オフラインで画像取得に失敗する。</strong> オフライン前に開いたページだけがキャッシュされています。<a href="/KomaYomi-docs/ja/guide/remote">バックアップとリモート</a> を参照。</li></ul><h2 id="次に読む" tabindex="-1">次に読む <a class="header-anchor" href="#次に読む" aria-label="Permalink to &quot;次に読む&quot;">​</a></h2><ul><li>新規インストール：<a href="/KomaYomi-docs/ja/guide/installation">インストールと起動</a>。</li><li>画像の準備がまだ：<a href="/KomaYomi-docs/ja/guide/preprocess">画像の前処理と名前変更</a>。</li><li>画像を追加する：<a href="/KomaYomi-docs/ja/guide/gallery">ライブラリと取り込み</a>。</li><li>フォルダ構成が特殊：<a href="/KomaYomi-docs/ja/guide/folder-rules">フォルダ検出の規則</a>。</li><li>キーを探す：<a href="/KomaYomi-docs/ja/guide/shortcuts">ショートカット一覧</a>。</li><li>問題が起きた：<a href="/KomaYomi-docs/ja/faq">FAQ とトラブルシューティング</a>。</li></ul>',10))])}const K=n(p,[["render",u]]);export{Y as __pageData,K as default};
